{
  "items": [
    {
      "title": "German Socio-Economic Panel (SOEP-Core), 1984–2023",
      "url_or_doi": "https://www.diw.de/en/diw_01.c.960654.en/edition/soep-core_v40r__data_1984-2023__remote_edition.html",
      "justification": "One of Germany's most comprehensive longitudinal household surveys. Contains individual- and household-level data on income, employment, education, health, housing, family structures, life satisfaction, and social inequality. Covers the entire 2010s and the early 2020s, making it particularly valuable for studying changes in social conditions over time. Data are provided by the German Institute for Economic Research (DIW Berlin)."
    },
    {
      "title": "German General Social Survey (ALLBUS), 1980–2025",
      "url_or_doi": "https://www.gesis.org/en/allbus/data-and-documentation",
      "justification": "A nationally representative survey examining social attitudes, behaviors, and demographic characteristics in Germany. Includes indicators of social inequality, political trust, immigration attitudes, religion, family relationships, social integration, and subjective well-being. Repeated surveys allow comparisons across the 2010s and 2020s. Data are available through GESIS, with registration required for downloads."
    },
    {
      "title": "Eurostat – European Union Statistics on Income and Living Conditions (EU-SILC)",
      "url_or_doi": "https://ec.europa.eu/eurostat/en/web/income-and-living-conditions/information-data",
      "justification": "Provides harmonized annual indicators of income distribution, poverty, social exclusion, material deprivation, housing conditions, and household characteristics. Includes Germany throughout the 2010s and 2020s. Particularly useful for examining social inequalities and comparing German social conditions with those of other European countries. Data can be filtered by country, year, age, sex, and household characteristics."
    },
    {
      "title": "Eurostat – EU-SILC Public Use Microdata",
      "url_or_doi": "https://ec.europa.eu/eurostat/web/microdata/public-microdata/statistics-on-income-and-living-conditions",
      "justification": "Provides anonymized household- and individual-level survey data, including datasets for Germany. Covers income, household composition, employment, education, and living conditions. Suitable for researchers who want to perform their own statistical analyses rather than rely exclusively on published indicators. Availability varies by country and year, and public-use files have limitations compared with scientific-use microdata."
    },
    {
      "title": "Federal Statistical Office of Germany (Destatis) – GENESIS-Online Database",
      "url_or_doi": "https://www.destatis.de/EN/Service/OpenData/api-webservice.html",
      "justification": "Germany's official statistical database provides extensive national time series covering demographic changes, household structures, migration, education, employment, social protection, housing, health, and economic conditions. Many statistical series include observations from both the 2010s and 2020s. Data can be downloaded in CSV and Excel formats or accessed through an API. Particularly useful for constructing customized social indicator datasets."
    },
    {
      "title": "German Official Statistics – Social Reporting: Poverty and Social Conditions",
      "url_or_doi": "https://www.statistikportal.de/de/soziales-und-armut",
      "justification": "Official German social reporting provides comparable indicators on poverty risk, social exclusion, and minimum social security benefits at national and federal-state levels. Particularly relevant for investigating regional social disparities, welfare dependence, and changes in living conditions during the 2010s and 2020s."
    },
    {
      "title": "German Official Statistics – Income, Poverty Risk and Social Living Conditions",
      "url_or_doi": "https://www.statistikportal.de/de/sbe/ergebnisse/einkommen-armutsgefaehrdung-und-soziale-lebensbedingungen",
      "justification": "Provides official indicators of income distribution, poverty risk, and social exclusion across Germany and its federal states. Draws on EU-SILC and the German Microcensus. Particularly useful for analyzing differences between regions, assessing income inequality, and monitoring poverty-related social conditions. Researchers should account for methodological changes in the underlying data sources around 2020."
    },
    {
      "title": "German Federal Employment Agency – Historical Unemployment and Labor Market Statistics",
      "url_or_doi": "https://statistik.arbeitsagentur.de/DE/Navigation/Statistiken/Fachstatistiken/Arbeitsuche-Arbeitslosigkeit-Unterbeschaeftigung/Produkte/Zeitreihen-Arbeitslose-Arbeitsuchende-Arbeitslosenquoten/Zeitreihen-Arbeitslose-Arbeitsuchende-Arbeitslosenquoten-Nav.html",
      "justification": "Official monthly and annual labor market data covering unemployment, underemployment, job vacancies, and employment across Germany. Includes historical series extending well before 2010 and continuing into the 2020s. Provides breakdowns by age, sex, nationality, disability status, and geographical region. Especially valuable for analyzing employment insecurity, regional labor market disparities, and the social effects of economic crises."
    },
    {
      "title": "Eurostat – At-Risk-of-Poverty Rate by Employment Status (EU-SILC)",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/product/view/ilc_li04?lang=en",
      "justification": "An annual dataset measuring poverty risk by employment status, age, and sex. Includes observations for Germany throughout the 2010s and 2020s, with overall coverage extending from 1995 to 2025. Useful for studying in-work poverty, the relationship between unemployment and poverty, and differences in economic vulnerability across demographic groups. Dataset code: ilc_li04."
    },
    {
      "title": "Eurostat – Material and Social Deprivation Rate by Age, Sex and Activity Status",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/product/page/ILC_MDSD01",
      "justification": "Annual indicators measuring material and social deprivation among different population groups. Includes German observations from 2014 onward, extending into the 2020s. Provides breakdowns by age, sex, and employment status. Particularly relevant for investigating living standards, economic hardship, and inequalities in access to essential goods and social participation. Dataset code: ilc_mdsd01."
    },
    {
      "title": "GESIS Panel – Longitudinal Survey of the German Population",
      "url_or_doi": "https://www.gesis.org/en/gesis-panel",
      "justification": "A longitudinal social science survey infrastructure providing repeated observations of individuals in Germany. Includes information on social attitudes, political preferences, personal circumstances, and various aspects of social behavior. Offers data collected during the 2010s and 2020s, making it useful for examining changes in public opinion, social cohesion, and individual experiences over time."
    },
    {
      "title": "GESIS Panel.pop – Data Access and COVID-19 Special Survey",
      "url_or_doi": "https://www.gesis.org/en/gesis-panel/data-access/data-access-gesis-panelpop",
      "justification": "Provides access to longitudinal survey data from the German population, including a special survey conducted in March 2020 concerning the coronavirus outbreak. Relevant for studying social conditions during the pandemic, including perceptions, attitudes, and behavioral responses. Can be combined with other GESIS Panel waves to investigate social changes across the 2020s. Standard data are available for secondary research, while access to certain sensitive variables is restricted."
    },
    {
      "title": "Eurostat – People at Risk of Poverty or Social Exclusion",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/view/ilc_peps01n",
      "justification": "Provides standardized statistics on the population experiencing poverty or social exclusion, including Germany. Supports analysis of socioeconomic vulnerability during the 2020s using the European Union's poverty and social exclusion framework. Particularly suitable for comparing Germany with other EU countries and examining differences across population groups. Researchers interested in the full 2010–2020 period should also consult the historical Europe 2020 indicator series because the indicator definition changed."
    },
    {
      "title": "German Federal Statistical Office – Regional Database Germany (Regionaldatenbank Deutschland)",
      "url_or_doi": "https://www.regionalstatistik.de",
      "justification": "Official regional statistical database providing indicators for German federal states, districts, and municipalities. Includes demographic characteristics, employment, education, migration, social benefits, housing, and other socioeconomic measures. Many series cover the 2010s and 2020s. Especially useful for analyzing regional inequalities, urban-rural differences, and geographical patterns in social conditions."
    },
    {
      "title": "GESIS Data Archive – German Social Science Survey Datasets",
      "url_or_doi": "https://www.gesis.org/en/services/finding-and-accessing-data/browse",
      "justification": "A research data discovery portal containing German survey datasets on social inequality, poverty, migration, integration, employment, health, gender relations, family life, political attitudes, and social participation. Includes cross-sectional and longitudinal studies conducted during the 2010s and 2020s. Particularly useful for identifying specialized datasets that complement official government statistics."
    },
    {
      "title": "Eurostat – EU-SILC Thematic Modules on Living Conditions",
      "url_or_doi": "https://ec.europa.eu/eurostat/web/income-and-living-conditions/database/modules",
      "justification": "Provides information about specialized EU-SILC survey modules covering specific dimensions of social conditions. Relevant topics include social and cultural participation, material deprivation, children's living arrangements, access to healthcare, financial difficulties, and intergenerational inequality. Modules conducted during the 2010s and 2020s can provide more detailed information about German social conditions than standard annual indicators."
    }
  ]
}
